\set ON_ERROR_STOP on

do $roles$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then
    create role anon nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    create role service_role nologin bypassrls;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'mila_acesso_restrito') then
    create role mila_acesso_restrito nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'sol_acesso_restrito') then
    create role sol_acesso_restrito nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'fabio_agent') then
    create role fabio_agent nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'lia_acesso_restrito') then
    create role lia_acesso_restrito nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'maria_lareport_rpc') then
    create role maria_lareport_rpc nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'ml_jobs') then
    create role ml_jobs nologin;
  end if;
end;
$roles$;

create schema cron;

create table cron.job (
  jobid bigint generated by default as identity primary key,
  jobname text not null,
  schedule text not null,
  command text not null
);

create function cron.schedule(
  p_jobname text,
  p_schedule text,
  p_command text
)
returns bigint
language plpgsql
as $function$
declare
  v_jobid bigint;
begin
  insert into cron.job (jobname, schedule, command)
  values (p_jobname, p_schedule, p_command)
  returning jobid into v_jobid;
  return v_jobid;
end;
$function$;

create function cron.unschedule(p_jobid bigint)
returns boolean
language plpgsql
as $function$
begin
  delete from cron.job where jobid = p_jobid;
  return found;
end;
$function$;

create table public.whatsapp_caixas (
  id integer primary key,
  ativo boolean not null default true
);

insert into public.whatsapp_caixas (id, ativo)
values (1, true), (2, false);

