do $assert_expurge_and_acl$
begin
  if (select count(*) from public.webhook_debug_log) <> 0 then
    raise exception 'linhas legadas nao foram expurgadas';
  end if;

  if has_table_privilege('service_role', 'public.webhook_debug_log', 'insert') then
    raise exception 'service_role ainda escreve no debug legado';
  end if;

  if has_table_privilege('authenticated', 'public.whatsapp_caixa_webhook_secrets', 'select')
     or has_table_privilege('authenticated', 'public.webhook_diagnosticos_sanitizados', 'select') then
    raise exception 'authenticated leu tabela backend-only';
  end if;
end;
$assert_expurge_and_acl$;

insert into public.whatsapp_caixa_webhook_secrets (
  caixa_id,
  secret_hash_sha256
)
values
  (1, repeat('a', 64)),
  (2, repeat('b', 64));

do $assert_validator$
begin
  if not public.validar_webhook_caixa_hash(1, repeat('a', 64)) then
    raise exception 'hash correto da caixa ativa foi rejeitado';
  end if;
  if public.validar_webhook_caixa_hash(2, repeat('b', 64)) then
    raise exception 'caixa inativa foi aceita';
  end if;
  if public.validar_webhook_caixa_hash(1, repeat('b', 64))
     or public.validar_webhook_caixa_hash(null, null)
     or public.validar_webhook_caixa_hash(1, 'invalido') then
    raise exception 'hash invalido foi aceito';
  end if;
end;
$assert_validator$;

set role service_role;
insert into public.webhook_diagnosticos_sanitizados (
  correlation_id,
  caixa_id,
  event_type,
  route,
  result,
  occurred_at
)
values
  ('11111111-1111-4111-8111-111111111111', 1, 'messages', 'evasao', 'accepted', now() - interval '8 days'),
  ('22222222-2222-4222-8222-222222222222', 1, 'messages', 'evasao', 'accepted', now());

do $assert_authenticated_denied$
begin
  if public.expurgar_webhook_diagnosticos_sanitizados() <> 1 then
    raise exception 'retencao de sete dias divergiu';
  end if;
end;
$assert_authenticated_denied$;
reset role;

do $assert_retention$
begin
  if (select count(*) from public.webhook_diagnosticos_sanitizados) <> 1 then
    raise exception 'retencao de sete dias divergiu';
  end if;
end;
$assert_retention$;

create function public.fixture_webhook_debug_writer()
returns void
language sql
as $function$
  insert into public.webhook_debug_log (payload)
  values ('{}'::jsonb);
$function$;

do $assert_writer_guard$
declare
  v_writer text;
begin
  select p.proname
    into v_writer
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.prokind in ('f', 'p')
    and pg_get_functiondef(p.oid) ~* (
      '(insert[[:space:]]+into|update|delete[[:space:]]+from|'
      || 'truncate([[:space:]]+table)?)[[:space:]]+'
      || '(public[.])?webhook_debug_log'
    )
  limit 1;

  if v_writer is null then
    raise exception 'writer guard nao bloqueou escritor persistente';
  end if;
end;
$assert_writer_guard$;

drop function public.fixture_webhook_debug_writer();

